# -*- coding: utf-8 -*-
"""English translations, batch 9 (40: heresies, Puritans, China missionaries)."""
EN = {
"Arianism 阿里乌主义": dict(lesson="Demoting Christ from God to a creature",
 summary="It holds that the Son is not eternal God, but the highest creature the Father made in time—'there was a time when He was not.' Condemned as heresy by the Council of Nicaea, but its influence continues today (e.g. Jehovah's Witnesses).",
 witness="It demotes Christ from God to a creature, and the foundation of the gospel collapses—a creature cannot save people. Scripture declares the Word is God, of the same substance and eternity as the Father.",
 follow=[],
 caution=["Denying Christ's full, eternal deity","Claiming 'the Son is created; there was a time when He was not'","Robbing salvation of its foundation—a creature cannot redeem people"],
 applications=["Anyone who says 'Jesus is created, not true God' is a version of Arianism (e.g. Jehovah's Witnesses)","Remember: a creature cannot save people; denying Christ's deity is dismantling the foundation of salvation","Respond with John 1:1 'the Word was God' and John 8:58 'before Abraham was, I am'","Hold the Nicene faith: the Son is of the same substance, glory, and eternity as the Father"],
 prayer="Lord Jesus, You and the Father are one, 'the Word was God,' and before Abraham was, You are. Keep me from Arius' error, not demoting You from God to a creature; let me hold fast Your full deity, for only true God can save me. Amen."),
"Socinianism 索西努主义": dict(lesson="Deleting the gospel's core by reason",
 summary="It denies the Trinity, Christ's deity, and the atonement, treating Jesus only as a moral example. It directly gave rise to modern Unitarianism.",
 witness="In the name of reason it deletes the gospel's core (Trinity, deity, atonement), leaving only a good man to imitate, with nowhere for salvation to rest.",
 follow=[],
 caution=["Denying the Trinity and Christ's full deity","Denying Christ's atonement, viewing Jesus only as a moral example","Setting human reason above Scripture's revelation"],
 applications=["Beware 'modern Unitarianism' that deletes Trinity, deity, and atonement 'in the name of reason'","If Jesus is only a moral example, not God, and never atoned, the gospel is hollow","Let reason serve Scripture, not trim revelation","Hold firm: Christ is fully God, and His substitutionary death truly bore our sins"],
 prayer="Lord, do not let me delete the gospel's core in the name of reason. Make me hold the Trinity, Christ's deity, and Your true atonement, knowing You are not only a moral example but the Savior who shed blood for me; and let my reason humbly submit to Your revelation. Amen."),
"Docetism 幻影说": dict(lesson="Denying Christ's true humanity",
 summary="It holds that Jesus had only deity, His flesh a mere 'appearance/phantom,' since the divine could not truly have flesh and truly suffer and die. One of the most dangerous early christological errors.",
 witness="If Christ had no true humanity, He did not truly die for us, and redemption is false too. The apostle John especially stressed 'the Word became flesh,' and to test 'whoever confesses Jesus Christ has come in the flesh.'",
 follow=[],
 caution=["Denying Christ's true flesh and humanity","Claiming His suffering and death were only appearance","If His humanity is false, His atoning death is in vain"],
 applications=["Be alert to any view that downplays Christ's true humanity and true suffering","If His flesh and death are an illusion, your redemption falls through too","Use the test of 1 John 4:2-3: 'whoever confesses Jesus Christ has come in the flesh'","Hold firm: the Word truly became flesh, truly hungered, tired, suffered, bled, died, and rose"],
 prayer="Lord Jesus, You truly became flesh, truly hungered, tired, suffered, bled, died, and rose. Keep me from docetism, treating Your humanity as an illusion; let me firmly believe You truly died for me, so my redemption is utterly real. Amen."),
"Gnosticism 诺斯底主义": dict(lesson="Replacing the gospel with secret knowledge",
 summary="It holds that matter is evil and only the spiritual is good, that one is saved by 'secret knowledge (gnosis)' rather than faith, and it disparages creation and the incarnation. Irenaeus systematically refuted it in 'Against Heresies.'",
 witness="It replaces the gospel received by faith with 'secret knowledge,' and by disparaging matter denies the goodness of creation and bodily resurrection. But the gospel is openly proclaimed to all, by faith, not by secret knowledge.",
 follow=[],
 caution=["Replacing the gospel of salvation by faith with 'secret knowledge'","Viewing matter as evil, disparaging creation and bodily resurrection","Creating a spiritual elite, turning the gospel into esoteric transmission"],
 applications=["Beware elitist teaching that 'one is saved only by secret knowledge / a higher spiritual level'","The gospel is openly proclaimed to all, not the esoteric knowledge of a few","Don't deny the goodness of creation and bodily resurrection by disparaging body/matter","Hold firm: salvation is only by receiving Christ through faith; what God made is good"],
 prayer="Lord, Your gospel is openly proclaimed to all, not the secret knowledge of a few. Keep me from Gnostic spiritual elitism, not despising Your good creation and bodily resurrection; let me receive Your free salvation by faith alone. Amen."),
"Nestorianism 聂斯托利主义": dict(lesson="Over-separating Christ's divine and human natures",
 summary="It tends to over-separate Christ's divine and human natures, almost speaking of 'two persons,' and was judged an error by the Council of Ephesus (orthodoxy holds: one person, divine and human natures neither confused nor separated).",
 witness="Cutting Christ's divine and human natures too far apart shakes the foundation of salvation that 'the one who is both God and man died for us.'",
 follow=[],
 caution=["Separating Christ's deity and humanity to nearly two persons","Shaking the orthodoxy of 'one Christ, divine and human natures united'","The error blurs the incarnation and redemption"],
 applications=["Beware views that cut Christ's two natures too far apart, almost speaking of 'two Christs'","Salvation needs 'the one who is both God and man' to die for us—the two natures cannot be separated","Hold Chalcedon: one person, divine and human natures, neither confused nor separated","When you meet vague christology, return to Scripture's clear witness to discern"],
 prayer="Lord Jesus, You are one person, yet with full deity and full humanity, neither confused nor separated. Make me hold this mystery, not cutting You into 'two Christs'; for only You, truly God and truly man, can be my Mediator and die for me. Amen."),
"Eutychianism / Monophysitism 优提克主义（基督一性论）": dict(lesson="The humanity swallowed by the deity",
 summary="Going to the other extreme, it holds Christ has only 'one nature'—the humanity swallowed and fused by the deity. It was rejected by the Council of Chalcedon (orthodoxy: the divine and human natures 'without confusion, without change, without division, without separation').",
 witness="If the humanity is swallowed by the deity, Christ is no longer truly man, and cannot be our true Mediator and ransom.",
 follow=[],
 caution=["Holding Christ has only one nature, the humanity fused and swallowed by the deity","Denying Chalcedon's orthodoxy of 'two natures united in one person'","Making Christ no longer truly man"],
 applications=["Beware the other extreme: speaking of Christ as 'having only one nature, the humanity swallowed by the deity'","If the humanity is swallowed, He is not truly man and cannot be our true Mediator","Hold firm: He was made like His brothers in every way, able to sympathize with our weakness","Between the two extremes (separation/fusion), keep the Chalcedonian balance"],
 prayer="Lord Jesus, Your humanity was not swallowed by Your deity; You were made like Your brothers in every way and can sympathize with my weakness. Keep me, between the two extremes, holding the Chalcedonian balance, not fusing Your two natures into one; let me rest in the Savior who is both God and man. Amen."),
"Pelagianism 伯拉纠主义": dict(lesson="Exalting human will, denying original sin",
 summary="It holds that people can do good and be saved by their own free will, denying or greatly minimizing the effect of original sin, regarding human nature as undamaged. Augustine refuted it with 'it is all grace' and it was condemned as heresy.",
 witness="It exalts human ability and weakens grace—if people can do good and be saved by themselves, Christ's cross is superfluous. Scripture says people are dead in sin, saved only by grace.",
 follow=[],
 caution=["Denying or greatly minimizing original sin's corruption of human nature","Holding people can do good and save themselves by free will","Weakening grace, making Christ's redemption superfluous"],
 applications=["Beware the optimistic view of man that 'human nature is undamaged, saved by free will'","If people can do good and be saved by themselves, Christ's cross is superfluous—this is the crux","Respond with Eph 2:1 'dead in trespasses and sins' and John 15:5 'apart from Me you can do nothing'","Hold firm: man is totally depraved; salvation is all God's grace"],
 prayer="Lord, I was dead in trespasses and sins, and apart from You I can do nothing. Tear down the Pelagian self-righteousness and self-confidence in me, that I confess man is totally depraved and salvation is all Your grace, no longer relying on my good works, only boasting in Your cross. Amen."),
"Semi-Pelagianism 半伯拉纠主义": dict(lesson="Crediting the start of salvation to man",
 summary="Milder than Pelagius: it holds salvation 'begins with man' taking the first step, and then God helps. It still credits part of the initiative of salvation to man, and was rejected by later councils.",
 witness="It credits the start of salvation to man, still weakening the truth that 'grace comes first'—Scripture says God first seeks, first loves, first opens the heart.",
 follow=[],
 caution=["Holding man takes the first step, and then God helps","Weakening that 'God's grace comes first, seeking man on His own initiative'","Subtly crediting part of salvation's merit to man"],
 applications=["Beware the milder version: 'man takes the first step, then God helps'","The start of salvation is also God's—He first seeks, first loves, first opens the heart","Watch whether you secretly credit a bit of your coming to faith to yourself","Hold firm: from election to repentance to perseverance, grace comes first at every step"],
 prayer="Lord, You first sought me, first loved me, first opened my heart. Make me not secretly credit the start of salvation to myself, confessing that from election, repentance, to perseverance, every step is Your grace going before; let all glory be Yours. Amen."),
"Montanism 孟他努主义": dict(lesson="New revelation overriding Scripture's authority",
 summary="It claimed continuous 'new revelation' and new prophecy, exalting it to equal or even above apostolic tradition, accompanied by extreme asceticism and end-times frenzy. The church finally rejected its placing of new prophecy above Scripture.",
 witness="Its crux is letting 'the inner voice/new prophecy' override or stand equal with the completed apostolic revelation, shaking Scripture's final authority—a pattern that recurs through the ages.",
 follow=[],
 caution=["Exalting continuous new prophecy above apostolic revelation","Overriding or paralleling Scripture with an 'inner voice'","Accompanied by end-times frenzy and extreme asceticism"],
 applications=["Beware movements that raise 'new prophecy/inner voice' to equal or above Scripture","Every 'God told me' must return to completed Scripture for testing","End-times frenzy and extreme asceticism often accompany 'new revelation'—take note","Hold firm: Scripture is God's final, complete revelation, not to be added to or subtracted from"],
 prayer="Lord, Your word is the complete, final revelation. Keep me from being deceived by Montanist 'new prophecy,' not letting any inner voice override Your Scripture; make me return all things to Your completed word to discern, not dancing to end-times frenzy. Amen."),
"Extreme Mysticism 极端神秘主义": dict(lesson="Replacing Scripture with inner experience",
 summary="Pursuing intimate communion with God is good, but extremists raise 'inner impressions, visions, voices' above Scripture, determining truth by subjective experience, breaking free from the constraint of objective revelation.",
 witness="Experience and meditation, if not tested by Scripture, replace 'God says' with 'I felt,' most easily leading astray. Every impression should return to God's word to be discerned.",
 follow=[],
 caution=["Raising subjective impressions and visions above Scripture","Determining truth by an 'inner voice,' breaking free from objective revelation","Spiritual experience untested by God's word"],
 applications=["Pursuing intimacy with God is good, but 'I felt' cannot replace 'God says'","Test every inner experience by Scripture, not letting the subjective override objective revelation","Beware treating visions and voices as authority above Scripture","Hold firm: Isa 8:20 'to the law and to the testimony'—test every spirit"],
 prayer="Lord, I long for intimate communion with You; keep this longing from going astray. Make me not raise subjective impressions and visions above Your word, but make Scripture the standard for all experience, testing every spirit, lest I replace 'You say' with 'I felt.' Amen."),
"Thomas Müntzer 托马斯·闵采尔（千禧年狂热）": dict(lesson="Establishing an earthly kingdom of God by violence",
 summary="A radical of the Reformation who held that by new 'direct revelation of the Spirit' one should immediately establish an earthly kingdom of God by violence, launched the Peasants' War, and was finally defeated and executed. A classic case of 'confusing the kingdom with political violence.'",
 witness="He turned the spiritual kingdom into earthly violent revolution, and overrode Scripture with 'new revelation.' The Lord's kingdom is not of this world, not by the sword, but by truth and regeneration.",
 follow=[],
 caution=["Overriding Scripture with 'new revelation,' claiming to be God's spokesman","Holding that an earthly kingdom of God should be established immediately by violent revolution","Confusing the spiritual kingdom with an earthly political project"],
 applications=["Beware the frenzy of 'establishing an earthly kingdom of God immediately by new revelation and violence'","The Lord's kingdom is not of this world, not by the sword, but by truth and regeneration","Don't swap spiritual hope for earthly political revolution","Hold firm: the kingdom spreads gradually by the gospel; believers obey rulers and win people by love"],
 prayer="Lord, Your kingdom is not of this world, not by the sword, but by truth and regeneration. Keep me from Müntzer-like frenzy, not swapping spiritual hope for earthly violent revolution; make me obey rulers, win people by gospel and love, and await Your kingdom's gradual spread. Amen."),
"William Miller 威廉·米勒（日期预测）": dict(lesson="Presumptuously predicting the date of the end",
 summary="He predicted Christ would return in 1844, leading many followers to sell their property and wait, and when it failed ('the Great Disappointment'), several groups arose afterward. A representative of the recurring error of 'predicting the date of the end.'",
 witness="The Lord plainly said 'of that day and hour no one knows'; presumptuously setting a date oversteps God's sovereignty, and is repeatedly put to shame. Be watchful and prepared, not calculating dates.",
 follow=[],
 caution=["Predicting the date of the return against 'of that day and hour no one knows'","Making believers fix their faith on a wrong date rather than the Lord Himself","Spawning more errant groups after the prophecy failed"],
 applications=["Anyone who 'predicts Christ's return on a certain date' violates 'no one knows the day'","Don't fix your faith on a date, but on the Lord Himself","Failed prophecies often spawn new errant groups—discern at the source","Hold firm: be watchful and prepared, ready to meet the Lord, not calculating a timetable"],
 prayer="Lord, of that day and hour no one knows, only the Father. Keep me from presumptuously predicting Your return or fixing my faith on a timetable, but on You Yourself; make me watchful and prepared, ready at any time to meet You. Amen."),
"Indulgences & Papal Corruption 教权腐败与赎罪券体系": dict(lesson="Selling salvation, human authority over Christ",
 summary="In the late medieval period the church amassed wealth by selling 'indulgences' (Tetzel's slogan: 'as the coin in the coffer rings, the soul from purgatory springs'), the pope's power was absolutized (Innocent III), and life was extremely corrupt (the Borgia pope Alexander VI). This abuse directly provoked the Reformation.",
 witness="Treating salvation as a sellable commodity and raising papal authority above Christ is a double error of 'salvation by works/money' and 'man replacing Christ as head.' Salvation is free grace, and Christ alone is the head of the church.",
 follow=[],
 caution=["Treating salvation as a commodity buyable with money via indulgences","Absolutizing papal authority above Scripture and Christ","Corrupt curial living, using spiritual office for private gain"],
 applications=["Beware any practice linking 'salvation' to money or merit (variants exist in every age)","Also beware raising a person's/office's authority above Scripture and Christ","Salvation is free grace, and Christ alone is the head of the church","Hold firm: Eph 2:8-9, saved by grace through faith, not by works"],
 prayer="Lord, I am saved by grace through faith, not by works, and it cannot be bought. Keep me from every system linking salvation to money or merit, and let no person or office stand above You and Your word; make me look only to Christ, the one head of the church. Amen."),
"Mormonism 摩门教（后期圣徒教会）": dict(lesson="Adding new scriptures, men can become gods",
 summary="Joseph Smith claimed to receive new revelation, adding 'new scriptures' like the Book of Mormon, paralleling or even overriding the Bible, and held to polytheism and a view of God and man that 'men can become gods,' fundamentally different from orthodox Christianity.",
 witness="It adds new scriptures and changes 'who God is, who man is'—a compound of 'new revelation above Scripture' plus 'an errant view of God and man.' Scripture warns: anyone preaching another gospel is to be accursed.",
 follow=[],
 caution=["Paralleling or overriding Scripture with new scriptures like the Book of Mormon","Holding polytheism and a view that 'man can evolve into a god'","Departing from the one true God and the gospel of justification by faith"],
 applications=["Note Mormonism adds 'new scriptures' like the Book of Mormon, paralleling or overriding the Bible","The view that 'man can evolve into a god' contradicts Scripture's one true God","Friendly but clear: this differs from orthodox Christianity at the foundation","Hold firm: Scripture is complete revelation, God is the one true God, salvation is only by Christ"],
 prayer="Lord, You are the one true God, and Your word is complete and lacking nothing. Keep me from being deceived by Mormonism's 'new scriptures' and 'men becoming gods'; let me hold the pure gospel of the one true God and salvation only by Christ, not turning aside. Amen."),
"Jehovah's Witnesses 耶和华见证人（守望台）": dict(lesson="Denying Christ's full deity",
 summary="Taught by the Watchtower Society, it denies Christ's full deity (viewing Jesus as created, i.e. Michael), denies the Trinity and hell, and repeatedly predicted a failed end. Its own translation (New World Translation) is accused of being altered to fit its doctrine.",
 witness="Its core error is of one lineage with ancient Arianism—demoting Christ to a creature. But Scripture declares 'the Word was God,' and Thomas called the risen Lord 'my Lord and my God.'",
 follow=[],
 caution=["Denying Christ's full deity, viewing Him as a creature","Denying the Trinity, altering texts to fit doctrine","Repeatedly failed predictions of the end's date"],
 applications=["Jehovah's Witnesses deny Christ's deity (of Arius' lineage)—respond with John 1:1, John 20:28","Note their own translation altered texts to fit doctrine","Be gentle toward those who come to your door, yet clearly hold that Christ is God","Hold firm: the Word was God, and the risen Lord is 'my Lord and my God'"],
 prayer="Lord Jesus, on seeing You risen Thomas called You 'my Lord and my God.' Keep me from following the Jehovah's Witnesses in denying Your deity, nor be shaken by an altered translation; make me gentle toward those who come to my door, yet clearly exalt You as the true and living God. Amen."),
"Christian Science 基督教科学派": dict(lesson="Reducing sin and redemption to illusion",
 summary="Founded by Eddy, it holds that matter, disease, and sin are all 'illusions,' denies Christ's true atonement and the reality of the body, and overrides Scripture with 'Science and Health,' essentially departing from the Christian faith.",
 witness="It turns sin, suffering, and the cross into 'illusions,' which amounts to denying real sin and real redemption. Scripture faces real sin and Christ's real death and resurrection.",
 follow=[],
 caution=["Denying the reality of matter, sin, and disease, calling them illusions","Denying Christ's true atonement and bodily resurrection","Overriding Scripture with the founder's writings"],
 applications=["Beware the view that 'sin, disease, and suffering are all illusions'—this amounts to denying real redemption","Scripture faces real sin and Christ's real death and resurrection, without evasion","Note the pattern of overriding Scripture with the founder's writings","Hold firm: Christ truly bore our real sins on the cross"],
 prayer="Lord, my sin is real, and Your death and resurrection are real. Keep me from the falsehood that 'sin and suffering are all illusions'; make me face my own sin, truly come to the cross, and receive the redemption You really accomplished. Amen."),
"Unification Church 统一教": dict(lesson="Replacing Christ with the founder",
 summary="Sun Myung Moon claimed to be the 'Messiah' completing Christ's unfinished work, replaced Scripture's authority with the 'Divine Principle,' and his theology and view of marriage (mass blessing weddings) seriously departed from orthodoxy.",
 witness="It replaces the one Christ with a living 'new Messiah,' and replaces Scripture with a new scripture—a classic of 'the founder replacing Christ, new revelation overriding Scripture.'",
 follow=[],
 caution=["The founder claiming to be a new Messiah, replacing Christ","Replacing Scripture's supreme authority with the 'Divine Principle'","Theology and ethics seriously departing from the orthodox faith"],
 applications=["Stay away from anyone who 'claims to be a new Messiah/completing Christ's unfinished work'","Replacing Scripture with a new scripture like the 'Divine Principle' is a classic authority error","Remember the Lord's warning: false Christs will arise—do not believe, do not follow","Hold firm: the one Christ, Scripture as the supreme and complete authority"],
 prayer="Lord Jesus, You are the one Christ, and there is no salvation apart from You. Keep me from every sect that claims a 'new Messiah' and sets up a new scripture; when false Christs arise to deceive, let me not believe or follow, but follow only You and Your word. Amen."),
"Prosperity Gospel 成功神学（财富福音）": dict(lesson="Replacing the cross with wealth",
 summary="(Note: the charismatic movement as a whole is not heresy; this refers to extreme deviations within it.) It holds that faith must bring health and wealth, that giving is a 'seed' to 'harvest' a financial return, treating God as a tool to satisfy personal desire.",
 witness="It swaps the cross's self-denial for this-life riches, reducing the gospel to a means of gain. The Lord Jesus called people to take up the cross, and the apostles often had poverty and affliction; godliness with contentment is great gain.",
 follow=[],
 caution=["Treating faith and giving as means to obtain health and wealth","Replacing taking up the cross and self-denial with this-life prosperity","Instrumentalizing God into an ATM to satisfy personal desire"],
 applications=["(Charismatic ≠ heresy, but beware its extremes) faith is not a means to obtain health and wealth","Giving is from love and gratitude, not a 'seed for harvest' investment","The Lord calls people to take up the cross and deny self, not replace the cross with prosperity","Hold firm: godliness with contentment is great gain; treasure in heaven, not on earth"],
 prayer="Lord, godliness with contentment is great gain, and my treasure is in heaven, not on earth. Keep me from being deceived by the prosperity gospel, not treating faith and giving as means to get rich; make me willingly take up the cross and follow You, valuing the eternal over this-life prosperity. Amen."),
"New Apostolic Reformation 新使徒改革运动（NAR）": dict(lesson="Modern apostolic authority overriding Scripture",
 summary="(Likewise: charismatic as a whole ≠ heresy; this refers to its controversial claims.) It advocates modern 'apostles, prophets' with authority equal to Scripture's apostles, who can issue binding new revelation, and intervenes in society with a 'Seven Mountains' dominion theology.",
 witness="Its crux is that 'modern apostles'/prophets' new revelation' has near-Scriptural authority—falling back into the old pattern of 'new revelation overriding or paralleling Scripture.' The foundation of Scripture's apostles was laid once for all.",
 follow=[],
 caution=["Claiming modern 'apostles and prophets' have authority equal to Scripture's apostles","Paralleling or overriding Scripture with binding new revelation","'Dominion' theology confusing the kingdom with politics"],
 applications=["(Likewise: charismatic as a whole ≠ heresy) beware the claim that 'modern apostle-prophets have authority equal to Scripture'","Every new revelation must return to the laid apostolic foundation and Scripture's test","Note 'dominion/Seven Mountains' theology confusing the kingdom with politics","Hold firm: the church is built on the foundation of apostles and prophets (Scripture), with Christ as head"],
 prayer="Lord, the church is built on the foundation of apostles and prophets, with Christ as head, and Your word was once delivered to the saints. Keep me from letting 'modern apostle-prophets' new revelation' override Scripture, nor be confused by dominion theology mixing kingdom and politics; root me in Your complete word. Amen."),
"Peoples Temple 人民圣殿教": dict(lesson="Absolute worship of the leader leading to mass destruction",
 summary="Jim Jones controlled his followers through a personality cult, turning the group into a cult, and in 1978 at 'Jonestown' in Guyana caused the tragedy of over nine hundred forced mass suicides (by poison). An extreme case of 'absolute leader-authority' ending in destruction.",
 witness="When one person replaces Christ as the absolute authority and believers surrender their discernment and conscience, the end is destruction. Christ alone is the head of the church; no one may replace Him.",
 follow=[],
 caution=["Replacing worship of Christ with a personality cult","Manipulating followers into surrendering independent thought and conscience","Absolute authority and isolating control, ending in mass death"],
 applications=["Stay away at once from any group that demands absolute loyalty to a leader and surrender of independent thought and conscience","A healthy community exalts Christ and encourages searching Scripture, not a personality cult","Note 'isolating control, no questioning allowed' as a cult danger sign","Hold firm: Christ alone is the head of the church; test all things by Scripture"],
 prayer="Lord, Christ alone is the head of the church, and no one can replace Him. Keep me and my community from personality cults and manipulation, testing all things by Scripture; when someone demands I surrender my discernment and conscience, give me alertness and courage to leave. Amen."),
"Branch Davidians 大卫教派": dict(lesson="Self-proclaimed Christ, end-times armed resistance",
 summary="David Koresh claimed to be an end-times prophet/Christ, stockpiled weapons, controlled followers, and in 1993 stood off against law enforcement in Waco, Texas, finally with a fire killing dozens. Another cult case of 'self-proclaimed-Christ leader + end-times frenzy + violence.'",
 witness="Self-proclaimed Christ, end-times frenzy, and force combined are the dangerous recipe of cults through the ages. The Lord long warned: false Christs and false prophets will arise to deceive—do not believe, do not follow.",
 follow=[],
 caution=["The leader claiming to be an end-times prophet/Christ, replacing the true Christ","Controlling and imprisoning followers with end-times frenzy and force","Blind following ending in destruction"],
 applications=["Self-proclaimed Christ/end-times prophet, plus stockpiling arms for resistance, is a cult's dangerous recipe","Be alert to closed groups of 'salvation only by following me, everyone outside is the enemy'","Remember the Lord's word: false Christs and prophets will come—do not believe, do not go","Hold firm: the true Christ has come and will come again; salvation is in Him alone"],
 prayer="Lord Jesus, You long warned that false Christs and false prophets would arise to deceive. Keep me from every cult that claims to be Christ and controls people with end-times frenzy and force; let me hold that You have come and will come again, and salvation is in You alone. Amen."),
"Ten Patterns of Heresy 异端的十种常见模式": dict(lesson="Identifying the ten patterns of heresy",
 summary="More important than remembering hundreds of names is recognizing 'where the error lies.' Though heresies through the ages take varied forms, their core errors repeatedly fall into the following ten patterns—use them as a sieve to discern true from false.",
 witness="It all comes back to one thing: heresy always tampers with 'who God is, who Christ is, how one is saved, whether Scripture is supreme authority, who is the head of the church.' Hold these foundations and you won't be tossed by every wind of false teaching.",
 follow=[],
 caution=["Denying the Trinity—tampering with 'who God is' (Sabellius, Socinus)","Denying Christ's deity—Jesus demoted to a creature (Arius, Jehovah's Witnesses)","Denying Christ's humanity—the incarnation broken (Docetism, Eutyches)","Salvation by works—grace weakened (Pelagius, indulgences)","Salvation by secret knowledge—the gospel replaced (Gnosticism)","New revelation above Scripture—Scripture's authority weakened (Montanus, Mormonism, NAR)","Absolute leader-authority—Christ replaced by a man (Unification Church, Peoples Temple)","Prosperity gospel—the cross replaced by wealth (Prosperity Gospel)","Predicting the end's date—overstepping God's sovereignty (Miller, date-setting groups)","Building an earthly kingdom-of-God utopia—confusing kingdom with political project (Müntzer)"],
 applications=["Rather than remember hundreds of names, memorize these ten patterns, and you can identify a heresy on sight","For each new teaching, ask in turn: does it tamper with 'God, Christ, salvation, Scripture's authority, the church's head'?","Hold the foundations (Trinity, Christ's two natures, grace alone, Scripture alone, Christ as head), and you won't be tossed by false-teaching winds","Pick one pattern today, consider what new packaging it appears in now, and prepare a scriptural response"],
 prayer="Lord, give me the wisdom to discern spirits, that I may memorize the patterns of heresy, and whatever new packaging they wear, see how they tamper with 'who You are, who Christ is, how one is saved, whether Scripture is supreme authority, who is the church's head.' Root me in the pure faith, untossed by false-teaching winds, holding to what I believe to the end by Scripture alone. Amen."),
"William Perkins 威廉·帕金斯": dict(lesson="Linking doctrine to life, preaching aimed at the conscience",
 summary="Called the 'father of Puritanism.' A Cambridge theologian and preacher who systematically grounded Calvinism in 'practical theology' and a godly life. His classic 'The Art of Prophesying' taught that preaching should 'reveal Christ, aim at the conscience, and apply closely,' influencing a whole generation of Puritan preachers; and through 'casuistry' he counseled people on practical spiritual problems. Prolific in his writings, he trained many later Puritan leaders.",
 witness="He linked profound theology to the conscience and life of ordinary believers—truth is not for showing off learning, but to reach the heart and change lives. The Puritan pattern of 'rigorous doctrine + fervent devotion + practical application' was largely laid by him.",
 follow=["Grounding systematic theology in a practicable godly life, not leaving truth in the head","Preaching that aims at 'revealing Christ, the conscience, and close application,' not showing off learning","Helping ordinary believers with practical spiritual problems through 'conscience counseling'","Training and shaping the next generation of preachers, laying the Puritan pastoral pattern"],
 caution=[],
 applications=["When you hear sermons and read Scripture, does it stay as head knowledge, or become a godly life?","When preaching or sharing your faith, do you 'aim at the conscience and apply closely'?","Faith must answer ordinary people's practical question 'what should I do'—is your faith practical enough?","Today, turn a place where you 'understand the truth but haven't acted' into a concrete action"],
 prayer="Lord, Perkins linked profound truth to the conscience and life of ordinary people. Make my faith go beyond the head to aim at the conscience and be lived out; and make what I preach and share truly touch hearts and change lives. Amen."),
"Richard Sibbes 理查德·西布斯": dict(lesson="A bruised reed He will not break",
 summary="Called 'The Heavenly Doctor.' A famous London preacher and lecturer at Trinity Church, Cambridge. His classic 'The Bruised Reed' comforts wounded, weak, nearly-giving-up souls with great tenderness, based on 'a bruised reed He will not break, a smoldering wick He will not snuff out' (Isa 42:3). In the rigorous Puritan tradition, he represents the gentlest, most healing side.",
 witness="He proved pure doctrine can be wrapped in the tenderest heart—toward the weak and smoldering, God does not crush, but supports, heals, and fans the dying flame. This is the warmest side of Puritan devotion.",
 follow=["Comforting wounded, weak, nearly-giving-up souls with great tenderness","Keeping a loving pastoral heart within rigorous theology, the two not in conflict","Looking at a person not by their 'smoldering' present, but by what God will perfect in them","Healing people with Christ's mercy, not crushing them with the law"],
 caution=[],
 applications=["Toward the weak, the fallen, those nearly giving up, do you crush them or support them like Sibbes?","When you yourself are 'smoldering,' remember God does not snuff a smoldering wick but fans it","Truth and tenderness do not conflict—can you hold both the truth and a merciful heart?","Take initiative today to comfort someone in a low place, nearly giving up"],
 prayer="Lord, You are the God who will not break a bruised reed nor snuff a smoldering wick. Through Sibbes' heart teach me to heal the weak with tenderness, not crush them with the law; and when I myself am smoldering, support me and fan the flame within me. Amen."),
"Thomas Watson 托马斯·沃森": dict(lesson="Teaching doctrine clearly, vividly, and piercingly",
 summary="A Puritan preacher and prolific author who, ejected from the pulpit for nonconformity, still shepherded privately. Vivid in style, rich in metaphor, clear and powerful, his classics 'A Body of Divinity,' 'The Beatitudes,' 'The Doctrine of Repentance,' and 'The Blessed Life' are still loved today. He made profound doctrine understandable to all and full of application—a model of 'clear doctrine + practical application.'",
 witness="He let the most ordinary believer taste the sweetness of theology—good truth need not be obscure; it can be clear, vivid, and piercing. Even ejection from the pulpit could not stop him shepherding by his pen.",
 follow=["Making profound doctrine clear, vivid, and understandable to all","Feeding ordinary believers with rich metaphors and practical application","Continuing to serve by private shepherding and writing after being ejected from the pulpit","Persisting under restriction and pressure, turning the pulpit into the field of the pen"],
 caution=[],
 applications=["Can you explain the truth you believe so even a child understands?","Good doctrine is sweet—have you tasted joy in serious truth?","When circumstances hinder public service, there are other ways to continue (writing, private companionship)","Use a down-to-earth metaphor today to explain a truth to someone near you"],
 prayer="Lord, Watson explained profound truth clearly, vividly, and piercingly, and shepherded by pen even when ejected from the pulpit. Give me the gift of preaching truth clearly, that people taste doctrine's sweetness; and let me find faithful ways to serve You even when circumstances are limited. Amen."),
"Thomas Goodwin 托马斯·古德温": dict(lesson="The ascended Christ still cares for us with tenderness",
 summary="A Puritan Independent leader, president of Magdalen College Oxford, member of the Westminster Assembly, a theological heavyweight ranked with John Owen. His classic 'The Heart of Christ in Heaven' depicts the ascended Christ still caring for weak saints on earth with a tender heart—even when we suffer, are weak, or fall, our Savior in heaven loves us all the more tenderly.",
 witness="He let people see a Christ with 'a heart still beating for us in heaven'—salvation is not a cold transaction, but being held tightly by a Lord full of mercy who cares for us at every moment.",
 follow=["Revealing with profound theology that the ascended Christ still tenderly cares for weak saints","Helping shape the Reformed confessional standards at the Westminster Assembly","As an Independent leader, holding the conviction of governing the church by Scripture","Turning profound truth into real comfort for believers' hearts"],
 caution=[],
 applications=["Think Christ despises you when you're weak and fallen? Goodwin says: His heart cares for you all the more tenderly","Salvation is not a cold transaction, but being held by a Lord who cares for you every moment—do you know Him this way?","Let profound truth become real comfort for your soul, not just debate material","When you're weak today, look up and meditate on the One whose 'heart still beats for you in heaven'"],
 prayer="Lord Jesus, You ascended to heaven, yet Your heart is all the more tender toward weak me on earth. Through Goodwin make me deeply know Your love, not fleeing You when I fall and am weak but drawing nearer; let Your caring heart be my real comfort. Amen."),
"John Flavel 约翰·弗拉维": dict(lesson="Meditating on and trusting God's hidden providence",
 summary="A Puritan pastor in Dartmouth, England, ejected for nonconformity, who still risked secretly preaching and shepherding fishermen and common folk by the seaside and in the woods. His classic 'The Mystery of Providence' teaches people to meditate on, remember, and trust God's hidden arrangement in all of life's matters; and he wrote 'Keeping the Heart' on watching the inner self. Through bereavement and persecution, he found comfort in God's providence.",
 witness="He taught people to 'look back and count the footsteps of God's providence'—life's seemingly random, scattered events are all finely woven together by a wise and loving God. Seeing this, one finds rest in affliction.",
 follow=["Teaching believers to meditate on, remember, and trust God's hidden arrangement in life","After ejection, risking secret shepherding of common folk by the sea and in the woods, not abandoning the flock","Finding the deepest comfort in God's providence through bereavement and persecution","Valuing 'keeping the heart,' watching the inner over the outer"],
 caution=[],
 applications=["Looking back over your life, can you count the footsteps of God's hidden providence?","Seemingly random, scattered events are finely woven by God—what rest does this give you in affliction?","When circumstances hinder gathering, Flavel shepherded even by the sea and woods—do you have this heart for the flock?","Write down three things of God's 'hidden providence' in your life today, and thank Him"],
 prayer="Lord, Flavel taught me to meditate on Your hidden providence, finding comfort in You through bereavement and persecution. Open my eyes to see Your loving, wise weaving in all of life's matters; when I don't understand, let me still rest in Your good providence. Amen."),
"Stephen Charnock 斯蒂芬·恰诺克": dict(lesson="Worshipping by deeply knowing God's attributes",
 summary="A Puritan preacher and theologian whose classic 'The Existence and Attributes of God' is one of the most profound, rich works on God's attributes in the English-speaking world, meditating one by one on God's eternity, immutability, omniscience, omnipotence, holiness, wisdom, and faithfulness. He turned the knowledge of God from abstract dogma into living truth that brings one to bow in worship.",
 witness="He believed 'a wrong or shallow knowledge of God is the root of all sin and corruption'—so he devoted his life to leading people to a right, deep, reverent knowledge of who God is. The truer the knowledge of God, the more right the worship and life.",
 follow=["Leading people to know God's eternity, holiness, omniscience, and faithfulness through profound, rich meditation","Turning theology from abstract dogma into living truth that brings one to bow in worship","Believing 'a wrong knowledge of God' is the root of all corruption, so striving to correct it","Correcting people's view of sin and self by the knowledge of God's greatness"],
 caution=[],
 applications=["Is your knowledge of God deep and reverent, or vague and shallow?","'A wrong knowledge of God is the root of all sin'—what misconception of God do you need to correct today?","The truer the knowledge of God, the more right the worship and life—will you spend time meditating on who God is?","Pick one of God's attributes today (e.g. faithfulness, holiness), meditate quietly for ten minutes, and worship"],
 prayer="Lord, Charnock spent his life meditating on Your attributes, leading people to deeply know You and bow in worship. Make me too not content with a shallow, vague knowledge of You, but know who You are ever more deeply and truly; when I see Your greatness and holiness, let me rightly view sin and self, and worship You alone. Amen."),
"William Gurnall 威廉·格纳尔": dict(lesson="Putting on the full armor, standing and triumphing in the Lord",
 summary="A Puritan pastor in Lavenham, England, famous for his great work 'The Christian in Complete Armour'—built on Ephesians 6, it explains piece by piece the spiritual armor God gives, teaching believers how to see through, resist, and overcome the devil's schemes. Spurgeon said of this book, 'if I could keep only one book by a man, this would be one of them.'",
 witness="He saw the believer's whole life as a real spiritual war, reminding people: victory is not by flesh, but by putting on the full armor God gives, watchful in prayer, standing firm.",
 follow=["Systematically equipping believers to fight the spiritual war with 'The Christian in Complete Armour'","Teaching people to see through and resist the devil's schemes, not naive or careless in battle","Stressing victory is not by flesh, but by putting on God's armor and watchful prayer","Quietly writing a generation-building masterpiece in long-term ministry in one place"],
 caution=[],
 applications=["Do you realize the believer's whole life is a real spiritual war?","Victory is not by your flesh and will, but by putting on the full armor God gives—have you put it on?","Examine today: of truth, righteousness, faith, salvation, God's word—which piece of armor have you let slacken?","When tempted and attacked, practice 'standing firm, watchful in prayer,' not fighting by flesh"],
 prayer="Lord, Gurnall reminds me that life is a spiritual war. Make me daily put on the full armor You give—belt of truth, breastplate of righteousness, shield of faith to quench the fiery darts, Your word as sword—standing firm in You, overcoming the evil one's schemes. Amen."),
"Charles Wesley 查尔斯·卫斯理": dict(lesson="Turning gospel truth into enduring hymns",
 summary="John Wesley's brother and co-worker in the Methodist movement, hailed as one of history's greatest hymn writers, who wrote about six thousand hymns in his life, including, besides 'Holy, Holy, Holy,' many famous works like 'And Can It Be,' 'Hark! the Herald Angels Sing,' 'O for a Thousand Tongues,' and 'Jesus, Lover of My Soul.' He turned gospel truth into singable psalms, letting the fire of revival spread into hearts through song.",
 witness="He proved truth can be not only preached and argued, but sung—when the gospel becomes song, it enters the heart where the head cannot reach, sung through the generations, never ceasing.",
 follow=["Writing about six thousand hymns, turning profound gospel truth into singable psalms","Expressing wonder and gratitude at Christ's love in song (as in 'And Can It Be')","Driving the Methodist revival with his brother, strengthening believers through song","Letting truth enter hearts through melody, sung through the generations"],
 caution=[],
 applications=["Besides reasoning, do you use song and art to express and convey faith?","Next time you sing, attend to the truth in the lyrics, letting it move from the mouth's singing to the heart's believing","Have you ever been 'amazed' by Christ's love? Charles wrote six thousand hymns for this","Sing a hymn about the cross's love heartily today, making it a prayer to God"],
 prayer="Lord, Charles Wesley turned Your amazing love into six thousand enduring hymns. Make me too amazed by Your love, worshipping You not only with words but with song; let truth enter my heart through melody, and through me to others, singing Your beauty through the generations. Amen."),
"Howell Harris 豪厄尔·哈里斯": dict(lesson="Turning the fire of revival into footsteps and discipleship",
 summary="One of the main igniters of the Welsh Great Revival. Originally a teacher, after coming to the Lord he was full of fervor, traveling across Wales preaching in the open air, establishing countless 'societies' to disciple believers, and with co-workers like Daniel Rowland sparking the great spiritual revival of 18th-century Wales, affecting a nation's spiritual life.",
 witness="Starting from a real experience of regeneration, he turned fervor into footsteps, crossing the countryside to bring the gospel to common folk, and held the fire of revival with small-group discipleship—revival is not only momentary passion, but must be shepherded into lasting life.",
 follow=["Starting from a real experience of regeneration, fervently preaching in the open air across Wales","Establishing countless 'society' small groups, discipling converts and holding the fire of revival","Sparking a nation-affecting great revival with co-workers in one heart","Undaunted by persecution and toil, bringing the gospel to the rural common folk"],
 caution=[],
 applications=["A real experience of regeneration turns into action—has your faith gone from 'knowing' to 'fervent'?","Revival cannot stop at passion; it must be held by discipleship groups—are you continually building people up?","Are you willing to leave your comfort zone to bring the gospel to common folk 'outside the church'?","Pray today for spiritual revival in your area, and arrange to begin discipling someone"],
 prayer="Lord, Harris started from the fire of regeneration, traveling across Wales preaching and discipling, igniting a nation's revival. Kindle me too with a real regeneration, that I turn fire into footsteps and discipleship, not seeking momentary passion but solidly bringing people into life's growth. Amen."),
"William Romaine 威廉·罗曼": dict(lesson="Holding the pure gospel within a cold institution",
 summary="In the 18th-century English evangelical revival, one of the few ministers who stayed within the established church (Anglican) and firmly preached justification by faith. He preached faithfully for years in London, and wrote a trilogy 'The Life, Walk, and Triumph of Faith,' emphasizing the 'life of faith' lived only by looking to Christ, holding the pure gospel in a generally cold, hostile environment.",
 witness="When evangelicals were often pushed out and the institution was often cold, he chose to stay in it as an unquenchable lamp, proving one can faithfully hold and solidly shepherd even in an unfriendly environment, without drifting with the tide.",
 follow=["Faithfully preaching justification by faith for years in a generally cold, hostile environment","Teaching the life of faith lived only by looking to Christ, with 'The Life, Walk, and Triumph of Faith'","Choosing to stay within the institution as light for change, rather than just leaving","Steadily preaching and shepherding for decades, day in and day out"],
 caution=[],
 applications=["In an environment cold or even hostile to faith, can you still faithfully hold and be light?","'The life of faith' is living daily by looking to Christ—what do you live by today?","Not everyone is called to leave; sometimes God wants you to stay as light for change","Live out your faith quietly and firmly today in a setting unfriendly to faith"],
 prayer="Lord, Romaine faithfully preached the pure gospel for decades in a cold, hostile environment, teaching people to live only by looking to Christ. Make me too hold the truth in unfriendly environments as an unquenchable lamp, living daily by the faith that looks to You, not drifting with the tide. Amen."),
"Robert Morrison 马礼逊": dict(lesson="Willingly the first to sow and pave the way",
 summary="The first Protestant Christian missionary to China. Arriving in Guangzhou in 1807, in the cracks between the Qing court's strict ban on preaching and the East India Company's unwelcome, he worked alone and patiently for twenty-seven years. He single-handedly translated the first complete Chinese Bible, compiled the first Chinese-English dictionary, ran schools, and set up a printing press, laying the linguistic and textual foundation for all later missions to China. During his time in China he saw only a few believe, yet willingly was the first to sow and pave the way.",
 witness="He saw almost no fruit, yet buried his life in the hardest pioneering—translating Scripture, making dictionaries, paving the way—so that millions later could hear the gospel. The loneliness and patience of a pioneer is the most silent and weighty offering in missions history.",
 follow=["Persisting alone and patiently for twenty-seven years under the high pressure of the ban and isolation","Single-handedly translating the first complete Chinese Bible and compiling the first Chinese-English dictionary, laying a foundation for posterity","Seeing only a few come to the Lord in his life, yet willingly being a pioneer-sower","Serving silently through the hard labor of scholarship and text, not seeking immediate fruit"],
 caution=[],
 applications=["Pioneers often see no fruit—are you willing to be the one who 'sows and paves the way, with fruit coming later'?","In the most adverse and lonely circumstances, can you persist patiently like Morrison?","Solid language, culture, and text work is the foundation for the gospel to take root long-term; don't despise the 'hard labor'","Pray today for Bible translation and for pioneers in places the gospel struggles to enter"],
 prayer="Lord, Morrison endured alone twenty-seven years under the ban's high pressure, translating Scripture and making dictionaries, willingly the first to sow and pave the way. Give me a pioneer's patience, faithfully sowing when I see no fruit, trusting You will let later generations reap a full harvest. Amen."),
"William Milne 米怜": dict(lesson="Willingly behind the scenes, running schools to train people",
 summary="Morrison's most important co-worker. Arriving in China in 1813, he moved to Malacca because of the ban on preaching, founded the Anglo-Chinese College (a cradle for training Chinese preachers and East-West exchange), helped Morrison complete the Bible translation, published Chinese periodicals, and led the first Chinese pastor Liang Fa to the Lord and baptism. Though he died young (37), he trained people and laid a foundation for the Chinese church.",
 witness="He willingly was the 'second in command,' quietly paving the way, running schools, and training local workers beside another's pioneering—the fruit of missions is often borne together by countless people willing to stay behind the scenes.",
 follow=["Willingly a co-worker of the pioneer, paving the way, running schools, and publishing behind the scenes","Founding the Anglo-Chinese College, training local preaching talent for the Chinese church","Leading and building up the first generation of Chinese believers (e.g. Liang Fa)","Giving his all though dying young, devoting his life to the Chinese gospel"],
 caution=[],
 applications=["Are you willing to be the 'second in command,' quietly paving the way behind another, not grasping the lead credit?","Training locals and raising up the next generation of workers lasts longer than charging alone—are you raising people?","Whether life is long or short is in God's hands; the key is to offer all wholeheartedly","Go today to perfect and nurture someone younger or more promising than yourself"],
 prayer="Lord, Milne willingly was a co-worker, running schools and training people behind the scenes, laying a foundation for the Chinese church in a short life. Make me too gladly perfect others and nurture juniors, not grasping the lead credit; whether long or short, may I wholeheartedly devote my life to You. Amen."),
"James Legge 理雅各": dict(lesson="Deeply studying culture, building an East-West bridge",
 summary="A missionary to China and a great sinologist. He preached, ran schools, and shepherded for years in Malacca and Hong Kong, and devoted his life to rigorously translating the Chinese classics (the Four Books and Five Classics, etc.) into English as 'The Chinese Classics,' letting the West truly know Chinese thought and building a bridge of understanding between East and West. In old age he became Oxford's first professor of Chinese. He deeply respected the culture of the land he served, grounding the gospel dialogue in real understanding.",
 witness="He did not despise or take shallowly the Chinese culture, but studied it for a lifetime, proving that true missions means going with respect to understand the other, building the gospel dialogue on deep understanding.",
 follow=["Rigorously translating and annotating the Chinese classics for a lifetime, letting East and West truly understand each other","Deeply respecting the culture of the land he served, not despising or taking it shallowly","Using scholarship to serve missions, building a bridge of East-West understanding","Besides missions, schooling, and shepherding, being a pioneer of cultural communication"],
 caution=[],
 applications=["In bringing the gospel to people of a different culture, have you first truly known and respected their culture?","True missions is 'going with respect to understand,' not from a position above—have you done this?","Scholarship and profession can also bridge for the gospel—can your expertise serve God's kingdom?","Learn about the culture of a group different from you today, to prepare to witness to them better"],
 prayer="Lord, Legge deeply studied and respected Chinese culture for a lifetime, building an East-West bridge of understanding. Make me, in bringing the gospel to people of different cultures, hold a humble, respectful heart, first knowing and understanding them, building the gospel dialogue on real understanding. Amen."),
"Samuel Pollard 伯格理": dict(lesson="Identifying with the least brothers to the end",
 summary="An English Methodist missionary who went deep into the poorest, most discriminated-against Miao mountain regions of southwest China (Shimenkan in Yunnan-Guizhou). He identified with the lowliest people, created the 'Old Miao script (Pollard script)' for the scriptless Miao, translated Scripture, ran schools, and brought education and medicine, sparking a spiritual and cultural revival that changed the whole people's destiny. He finally died of typhoid contracted while caring for a sick student, and was buried at Shimenkan.",
 witness="He chose to live among the most despised people, creating a script for them, bringing dignity and the gospel, and finally laid down his life caring for the sick—this is the most concrete form of incarnate love: identifying with the least brothers to the end.",
 follow=["Going deep into the poorest, most discriminated-against Miao mountains, identifying and living with the lowliest","Creating a script for a people without writing, translating Scripture and running schools, bringing dignity and revival","Bringing the gospel, education, and medicine together to a neglected, marginalized people","Contracting illness and dying while caring for a sick student, loving to the point of laying down his life"],
 caution=[],
 applications=["Are you willing to draw near to and identify with society's most despised, neglected group?","True love is 'incarnate'—living among them, not charity from afar","Bringing dignity (education, writing, medicine) to the neglected is also preaching the gospel","Pray today for a marginalized group, and consider one concrete thing you can do for them"],
 prayer="Lord, Pollard lived among the most despised Miao, creating a script for them, bringing the gospel and dignity, and finally laid down his life caring for the sick. Give me this incarnate love that identifies with the least brothers to the end, drawing near to the neglected, bringing them Your gospel and dignity. Amen."),
"Lottie Moon 洛蒂·穆恩": dict(lesson="Sharing the people's hardships, self-giving unto death",
 summary="An American Southern Baptist woman missionary who went to Shandong, China in 1873, never married, served nearly forty years, focused on evangelizing women and children and running schools, deeply identified with the Chinese, wore Chinese dress, and lived in villages. In the famine of north China in her later years, she gave her own food and savings to the starving people, while she herself weakened from hunger and exhaustion, dying on the way back to America. The Southern Baptist 'Christmas Offering' campaign is named after her, still inspiring countless people to support missions.",
 witness="She not only preached the gospel, but shared her own food rations with the hungry, living to the point of 'starving herself for them'—even a single woman can pour out her whole life without reserve on a foreign field.",
 follow=["A single woman going to China for nearly forty years, a pioneer of missions to women and children","Deeply identifying with the Chinese, wearing Chinese dress, living in villages, mingling with the people","Giving her own food and savings to the people in famine, self-giving unto death","Inspiring an ongoing missions-offering campaign by the offering of her life"],
 caution=[],
 applications=["'Single' is no hindrance to service—Moon gave her whole life without reserve to the field","Are you willing to 'share the hardships' of those you serve, rather than give from above?","True love is sometimes giving away your own food rations—to what degree can you give?","Make a practical offering or intercession today for missionaries and workers in need on the front lines"],
 prayer="Lord, Lottie Moon went to China single for forty years, shared the people's hardships, gave her food rations in famine, and gave herself unto death. Make me, married or not, able to give my whole life to You, identify with and share the suffering of those I serve, and support front-line workers with practical offerings. Amen."),
"C.T. Studd 司徒德": dict(lesson="If Christ died for me, no sacrifice is too great",
 summary="A famous English cricket star who, at the height of fame and fortune, came to the Lord and gave himself, renouncing a huge inheritance, going successively to China (joining the China Inland Mission), India, and Africa (deep into the Congo interior in his later years), and founding the 'Worldwide Evangelization Crusade (WEC).' His famous saying: 'If Jesus Christ be God and died for me, then no sacrifice can be too great for me to make for Him.' His life went from a celebrity to a servant pioneering among the unreached.",
 witness="With his life he answered one question: if Christ is truly God and truly died for me, then what is there that I would not give up for Him? From a star adored by thousands to a servant in the Congo jungle, he is the most exhilarating footnote to 'total consecration.'",
 follow=["Willingly renouncing wealth and glory at the height of fame and fortune, wholly given to the Lord","Pioneering among the unreached across three continents—China, India, Africa","Founding a mission, sending people deep into the hardest, most neglected fields","Inspiring generation after generation of youth with a life of 'total consecration'"],
 caution=[],
 applications=["'If Christ truly died for me, what would I not give for Him?'—how does this challenge your choices today?","Fame, prospects, security—is there one you clutch and won't release for Christ?","Total consecration is not impulse, but a willing choice after seeing Christ's value clearly","Ask God honestly today: what is there that I haven't truly given to You?"],
 prayer="Lord, Studd gave up everything for You at the height of fame, saying 'if You died for me, no sacrifice is too great.' Make me too see Your incomparable value, release the fame and prospects I clutch, and give my whole life to You, gladly a pioneering servant. Amen."),
"John & Betty Stam 施达能夫妇": dict(lesson="Faithful unto death, entrusting all to God",
 summary="A young American missionary couple sent by the China Inland Mission to preach in Anhui. In 1934 the Red Army invaded; the two were captured, calmly wrote 'may the will of God be done,' and the next day were taken to the execution ground and beheaded as martyrs, only in their twenties. Their three-month-old daughter was hidden and miraculously rescued (later called 'the baby God cared for'). Before his martyrdom John Stam said: 'Lord, make us faithful unto death.' Their witness shook and inspired countless youth to give themselves to missions.",
 witness="A couple in their twenties entrusted their marriage, future, lives, and even their infant daughter into God's hands, calmly going to their death—'faithful unto death' was no slogan, but written with their blood under the blade.",
 follow=["A young couple devoting themselves together to missions, not forsaking their faith unto death","Still writing 'may the will of God be done' when captured and facing execution, going calmly to death","Entrusting their infant daughter wholly into God's hands","With lives in their twenties, living out 'faithful unto death' as a blood-written witness"],
 caution=[],
 applications=["'Lord, make us faithful unto death'—do you dare take this prayer seriously?","Entrusting future, marriage, and children into God's hands—have you truly let go and entrusted?","They gave all in their twenties—youth is no reason to shrink back, but a good time to give oneself","Entrust into God's hands today the one thing you most cling to and want to control"],
 prayer="Lord, the Stams were martyred for You in their twenties, saying even at execution 'may Your will be done,' entrusting their daughter to Your hands. Give me such trust, to entrust my future, my loved ones, and my life into Your hands; and make me too faithful unto death. Amen."),
"Eric Liddell 李爱锐": dict(lesson="Giving up glory for principle, serving people unto death",
 summary="A Scot, the 100-meter sprint champion at the 1924 Paris Olympics—because the race was scheduled on the Lord's Day, he insisted on keeping the Sabbath and did not run his strong 100-meter event, switching to the 400 meters and instead winning gold and breaking the record (depicted in the film 'Chariots of Fire'). At the height of glory, he returned to his birthplace, China (Tianjin), as a missionary and teacher. In WWII he was interned in the Japanese Weihsien camp, where amid hardship he served, encouraged, and taught the prisoners, giving away what little he had, finally falling ill from exhaustion and dying in the camp.",
 witness="At the peak of glory he chose to obey God's principle, and after glory chose the lowly field, and finally in the camp poured himself out for others—his talent, honor, and life he gladly gave back to God.",
 follow=["Preferring to give up his strong event to keep the Lord's Day on the Olympic track","Returning to China as a missionary and teacher despite his glory, willingly lowly","Serving, encouraging, and teaching the prisoners in the Japanese camp, giving all he had to others","Giving back his athletic talent, honor, and life to God, serving unto death"],
 caution=[],
 applications=["When 'success' conflicts with 'principle,' will you, like Liddell, hold to principle for your faith?","After glory comes, are you willing to choose a lowly, unremarkable field for Christ?","In hardship, do you look after yourself, or like him give away what little you have to others?","In one small matter today, lay down a bit of your own 'victory' for the sake of loyalty to God"],
 prayer="Lord, Liddell gave up his strong Olympic event to keep Your day, returned to serve in China after glory, and at last poured himself out for the prisoners in the camp. Make me hold loyalty to You when success conflicts with principle, and willingly lay down glory to serve people in lowly places to the end. Amen."),
}
